-- rule stored_level_drift (stored_metric): parameterized; p1 bigint
WITH RECURSIVE edge AS (SELECT DISTINCT t."parent_id" AS p, t."child_id" AS c FROM "sxc_rules"."bom_line" t WHERE t."parent_id" IS NOT NULL AND t."child_id" IS NOT NULL), h(node, d) AS (SELECT e.c, 0 FROM edge e WHERE NOT EXISTS (SELECT 1 FROM edge x WHERE x.p = e.c) UNION SELECT e.p, h.d + 1 FROM edge e JOIN h ON e.c = h.node WHERE h.d < CAST(:p1 AS bigint)), ht AS (SELECT h.node, max(h.d) AS height FROM h GROUP BY h.node) SELECT n."part_id", CASE WHEN EXISTS (SELECT 1 FROM edge x WHERE x.p = n."part_id") THEN CASE WHEN n."stored_level" = 0 THEN 'has_children_stored_zero' WHEN n."stored_level" < ht.height THEN 'stored_below' ELSE 'stored_above' END WHEN EXISTS (SELECT 1 FROM edge x WHERE x.c = n."part_id") THEN 'leaf_stored_nonzero' ELSE 'outside_stored_nonzero' END AS "kind", n."stored_level" AS "stored", COALESCE(ht.height, 0) AS "height" FROM "sxc_rules"."part" n LEFT JOIN ht ON ht.node = n."part_id" WHERE n."stored_level" IS NOT NULL AND n."stored_level" <> COALESCE(ht.height, 0);

-- rule stored_level_drift: view
CREATE OR REPLACE VIEW "sxc_out"."v_rule_stored_level_drift" AS
SELECT r.*, row_number() OVER (ORDER BY r."part_id" COLLATE "C" NULLS FIRST, r."kind" COLLATE "C" NULLS FIRST, r."stored" NULLS FIRST, r."height" NULLS FIRST) AS ord FROM (WITH RECURSIVE edge AS (SELECT DISTINCT t."parent_id" AS p, t."child_id" AS c FROM "sxc_rules"."bom_line" t WHERE t."parent_id" IS NOT NULL AND t."child_id" IS NOT NULL), h(node, d) AS (SELECT e.c, 0 FROM edge e WHERE NOT EXISTS (SELECT 1 FROM edge x WHERE x.p = e.c) UNION SELECT e.p, h.d + 1 FROM edge e JOIN h ON e.c = h.node WHERE h.d < CAST(E'17' AS bigint)), ht AS (SELECT h.node, max(h.d) AS height FROM h GROUP BY h.node) SELECT n."part_id", CASE WHEN EXISTS (SELECT 1 FROM edge x WHERE x.p = n."part_id") THEN CASE WHEN n."stored_level" = 0 THEN 'has_children_stored_zero' WHEN n."stored_level" < ht.height THEN 'stored_below' ELSE 'stored_above' END WHEN EXISTS (SELECT 1 FROM edge x WHERE x.c = n."part_id") THEN 'leaf_stored_nonzero' ELSE 'outside_stored_nonzero' END AS "kind", n."stored_level" AS "stored", COALESCE(ht.height, 0) AS "height" FROM "sxc_rules"."part" n LEFT JOIN ht ON ht.node = n."part_id" WHERE n."stored_level" IS NOT NULL AND n."stored_level" <> COALESCE(ht.height, 0)) r;

-- example stored_level_drift[0]: parameterized; 15 parameters
WITH "sxc_ex_part"("part_id", "stored_level") AS (VALUES (CAST(:p1 AS text), CAST(:p2 AS integer)), (CAST(:p3 AS text), CAST(:p4 AS integer)), (CAST(:p5 AS text), CAST(:p6 AS integer)), (CAST(:p7 AS text), CAST(:p8 AS integer)), (CAST(:p9 AS text), CAST(:p10 AS integer))), "sxc_ex_bom_line"("parent_id", "child_id") AS (VALUES (CAST(:p11 AS text), CAST(:p12 AS text)), (CAST(:p13 AS text), CAST(:p14 AS text))) SELECT * FROM (WITH RECURSIVE edge AS (SELECT DISTINCT t."parent_id" AS p, t."child_id" AS c FROM "sxc_ex_bom_line" t WHERE t."parent_id" IS NOT NULL AND t."child_id" IS NOT NULL), h(node, d) AS (SELECT e.c, 0 FROM edge e WHERE NOT EXISTS (SELECT 1 FROM edge x WHERE x.p = e.c) UNION SELECT e.p, h.d + 1 FROM edge e JOIN h ON e.c = h.node WHERE h.d < CAST(:p15 AS bigint)), ht AS (SELECT h.node, max(h.d) AS height FROM h GROUP BY h.node) SELECT n."part_id", CASE WHEN EXISTS (SELECT 1 FROM edge x WHERE x.p = n."part_id") THEN CASE WHEN n."stored_level" = 0 THEN 'has_children_stored_zero' WHEN n."stored_level" < ht.height THEN 'stored_below' ELSE 'stored_above' END WHEN EXISTS (SELECT 1 FROM edge x WHERE x.c = n."part_id") THEN 'leaf_stored_nonzero' ELSE 'outside_stored_nonzero' END AS "kind", n."stored_level" AS "stored", COALESCE(ht.height, 0) AS "height" FROM "sxc_ex_part" n LEFT JOIN ht ON ht.node = n."part_id" WHERE n."stored_level" IS NOT NULL AND n."stored_level" <> COALESCE(ht.height, 0)) r;
